meta.content:
default-src 'self' 'unsafe-inline' 'unsafe-eval' https: data: blob:;
                               script-src 'self' 'unsafe-inline' 'unsafe-eval' https:;
                               style-src 'self' 'unsafe-inline' https:;
                               img-src 'self' https: data: blob:;
                               connect-src 'self' https: wss:;
                               font-src 'self' https: data:;

head.script:
window.csrf_token = "";
// MAX WebView fallback: если session_id есть в localStorage,
// устанавливаем его как cookie (cross-site ограничения
// могут блокировать автоматическое сохранение cookie).
(function() {
    var sid = localStorage.getItem('rost_max_session_id');
    if (sid) {
        document.cookie = 'session_id=' + sid + '; path=/; SameSite=None; Secure';
    }
})();

                  (function() {
                    var root = document.getElementById('root');
                    function showError(msg, stack) {
                      if (!root) return;
                      root.innerHTML = '
' +
                        'JS Error: ' + (msg || 'unknown') +
                        (stack ? '\n\nStack:\n' + stack : '') +
                      '';
                      root.style.background = '#fff0f0';
                      root.style.minHeight = '100vh';
                    }
                    window.addEventListener('error', function(e) {
                      showError(e.message, e.error?.stack);
                    });
                    window.addEventListener('unhandledrejection', function(e) {
                      showError(e.reason?.message || String(e.reason), e.reason?.stack);
                    });
                    // Check if root exists after DOM ready
                    if (!document.getElementById('root')) {
                      showError('Root element not found in DOM');
                    }
                  })();
